using UnityEngine;
namespace MetaPort.Games.MiniGolf { public class GolfManager : MonoBehaviour { public Transform ball; public Transform club; void Awake(){ var go=GameObject.CreatePrimitive(PrimitiveType.Sphere); go.name="GolfBall"; go.transform.SetParent(transform,false); go.transform.localPosition=Vector3.forward*2f; ball=go.transform; } void Update(){ var hm=HandTracking.HandTrackingManager.Instance; if(hm!=null && hm.IsTracking(Core.MonadoOpenXRLoader.Handedness.Right)){ var pos=hm.GetHandPosition(Core.MonadoOpenXRLoader.Handedness.Right); if(club==null){ var c=GameObject.CreatePrimitive(PrimitiveType.Cylinder); c.name="GolfClub"; c.transform.localScale=new Vector3(0.02f,0.5f,0.02f); club=c.transform; } club.position=pos; } } } }
